    #supplier-portal-vbcs .sp-section { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; overflow: hidden; }
    #supplier-portal-vbcs .sp-section-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 16px; border-bottom: 1px solid #e5e7eb; }
